def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    # Build the namespace for the new class
    namespace = {}
    # Use __slots__ to prevent dynamic attribute creation
    namespace['__slots__'] = tuple(fields)
    # Store the SRID mapping on the class
    namespace['_srid_map'] = srid_map
    # Create annotations for type checking (use string to avoid importing typing)
    annotations = {}
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise TypeError(f"Invalid field name: {f!r}")
        annotations[f] = 'typing.Any'
    namespace['__annotations__'] = annotations
    # Create and return the new subclass of Point
    return type(name, (Point,), namespace)

