def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        return (0,)
    parts = s.strip().split('.')
    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            # Extract leading digits if any
            num = ''
            for ch in part:
                if ch.isdigit():
                    num += ch
                else:
                    break
            nums.append(int(num) if num else 0)
    return tuple(nums)

