def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        order = []  # list of keys in LRU order, oldest first

        def make_key(args, kwargs):
            if typed:
                key = tuple((arg, type(arg)) for arg in args)
                key += tuple((k, v, type(v)) for k, v in kwargs.items())
            else:
                key = args
                key += tuple(kwargs.items())
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            if key in cache:
                value, ts = cache[key]
                if now - ts <= ttl:
                    # Update LRU order
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    return value
                else:
                    # expired
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                oldest = order.pop(0)
                del cache[oldest]
            cache[key] = (result, now)
            order.append(key)
            return result

        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        usage = {}

        def wrapper(*args, **kwargs):
            # Build a hashable key from arguments
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include the type of each argument in the key
                key += tuple(type(v) for v in args)
                key += tuple(type(v) for v in kwargs.values())
            if key in cache:
                usage[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            usage[key] = 1
            if len(cache) > maxsize:
                # Evict the least frequently used item
                min_count = min(usage.values())
                for k in list(usage):
                    if usage[k] == min_count:
                        del cache[k]
                        del usage[k]
                        break
            return result

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper

    # Support usage as @lfu_cache without parentheses
    if callable(maxsize):
        func = maxsize
        return decorator(func)
    return decorator

