def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to retrieve the error array for the given coordinate.
    err = None
    if hasattr(self, "errors") and coord_name in self.errors:
        err = self.errors[coord_name]
    elif hasattr(self, "Data") and coord_name in self.Data:
        err = self.Data[coord_name].get("err")
    # If no error information is available, return an empty array.
