def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    log = getattr(self, 'validation_log', getattr(self, 'log', []))
    lines = []
    for entry in log:
        if isinstance(entry, str):
            lines.append(f"{prefix}{entry}")
        elif isinstance(entry, dict):
            status = entry.get('status', '')
            message = entry.get('message', '')
            lines.append(f"{prefix}{status}: {message}")
        else:
            lines.append(f"{prefix}{entry}")
    return "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing = []
    for file, digest in manifest_files.items():
        if digest not in digests_used:
            missing.append((file, digest))
    if missing:
        msg = ", ".join(f"{f}:{d}" for f, d in missing)
        raise ValueError(f"Missing digests for files: {msg}")
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    for logical_path, entries in inventory.items():
        files = set()
        # Handle mapping of version -> content_file
        if isinstance(entries, dict):
            for ver, content_file in entries.items():
                try:
                    if ver >= version:
                        files.add(content_file)
                except Exception:
                    # Fallback to string comparison if types differ
                    if str(ver) >= str(version):
                        files.add(content_file)
        # Handle list of entries
        elif isinstance(entries, list):
            for entry in entries:
                ver = None
                content_file = None
                if isinstance(entry, dict):
                    ver = entry.get("version")
                    content_file = entry.get("content_file")
                elif isinstance(entry, tuple) and len(entry) == 2:
                    content_file, ver = entry
                if ver is None or content_file is None:
                    continue
                try:
                    if ver >= version:
                        files.add(content_file)
                except Exception:
                    if str(ver) >= str(version):
                        files.add(content_file)
        if files:
            result[logical_path] = files
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")
        if 'path' not in entry:
            raise ValueError("File entry missing 'path'")
        path = entry['path']
        if path not in manifest_files:
            raise ValueError(f"File '{path}' in fixity block not present in manifest")
        if 'hash' in entry and not isinstance(entry['hash'], str):
            raise ValueError(f"Hash for file '{path}' must be a string")
        if 'size' in entry and not isinstance(entry['size'], int):
            raise ValueError(f"Size for file '{path}' must be an integer")
    return True

def files_list(path):
    """Return the files in `path`"""
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        return [
            os.path.abspath(os.path.join(path, f))
            for f in os.listdir(path)
            if os.path.isfile(os.path.join(path, f))
        ]
    return []

def add_rendition(self, lang, file_path):
    """
    Adds a language-specific rendition of a file to the internal mapping.

    The mapping is stored in ``self.renditions`` as a dictionary where the
    key is the original file name and the value is another dictionary that
    maps language codes to the corresponding rendition file paths.

    Example mapping::

        {
            "artigo02.pdf": {
                "en": "artigo02-en.pdf",
                "es": "artigo02-es.pdf"
            }
        }

    Args:
        lang: Language code of the rendition (e.g. ``"en"``).
        file_path: Full path or file name of the rendition file.

    Returns:
        None
    """
    # Ensure the renditions dictionary exists
    if not hasattr(self, "renditions"):
        self.renditions = {}

    # Determine the original file name by stripping the language suffix
    base, ext = os.path.splitext(file_path)
    # Remove the language suffix (e.g. "-en") from the base name
    if base.endswith(f"-{lang}"):
        original_base = base[: -len(f"-{lang}")]
    else:
        # If the naming convention is not followed, fall back to the base
        original_base = base
    original = original_base + ext

    # Add the rendition to the mapping
    if original not in self.renditions:
        self.renditions[original] = {}
    self.renditions[original][lang] = file_path

    # No explicit return value needed; the mapping is updated in place.

