def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, (list, tuple)):
        raise TypeError('pieces must be a list or tuple')
    rendered = []
    for piece in pieces:
        if hasattr(piece, 'render') and callable(piece.render):
            rendered.append(piece.render(style))
        else:
            rendered.append(str(piece))
    if style == 'html':
        return '<br>'.join(rendered)
    elif style == 'markdown':
        return '\n\n'.join(rendered)
    elif style == 'plain':
        return '\n'.join(rendered)
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    else:
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd = commands.split()
    else:
        cmd = list(commands)
    if args:
        if isinstance(args, str):
            cmd += args.split()
        else:
            cmd += list(args)
    # Verbose output
    if verbose:
        print('Running command:', ' '.join(cmd))
    # Configure stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            check=True,
            text=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise e

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(func):
        """Store func in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = func
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    root = getattr(self, 'root', None)
    if root is None:
        raise AttributeError("Root path not defined")

    for dirpath, dirnames, filenames in os.walk(root):
        for filename in filenames:
            # Skip digest files themselves
            if filename.endswith('.digest'):
                continue

            num_objects += 1
            file_path = os.path.join(dirpath, filename)
            valid = True

            if validate_objects:
                try:
                    self._validate_object(file_path)
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Validation failed for {file_path}: {e}")

            if check_digests and valid:
                digest_path = file_path + '.digest'
                if os.path.exists(digest_path):
                    try:
                        with open(digest_path, 'r') as f:
                            expected = f.read().strip()
                        actual = hashlib.sha256()
                        with open(file_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                actual.update(chunk)
                        actual_hex = actual.hexdigest()
                        if actual_hex != expected:
                            valid = False
                            if show_warnings:
                                print(f"Digest mismatch for {file_path}: expected {expected}, got {actual_hex}")
                    except Exception as e:
                        valid = False
                        if show_warnings:
                            print(f"Digest check failed for {file_path}: {e}")

            if valid:
                good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    version = version.strip()
    parts = version.split('.')
    # Find the last numeric component to increment
    for i in range(len(parts) - 1, -1, -1):
        if parts[i].isdigit():
            width = len(parts[i])
            new_val = str(int(parts[i]) + 1)
            if len(new_val) < width:
                new_val = new_val.rjust(width, '0')
            parts[i] = new_val
            break
    else:
        # No numeric component found; return original
        return version
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against
    if not hasattr(self, 'root_inventory') or self.root_inventory is None:
        raise ValueError('Root inventory not set; cannot validate version inventories')

    # Record of digests that differ from the root inventory
    self.different_digests = {}

    for vdir in version_dirs:
        inv_path = os.path.join(self.inventory_dir, vdir, 'inventory.json')
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f'Inventory file missing for version {vdir}')

        with open(inv_path, 'r') as f:
            try:
                inv = json.load(f)
            except Exception as exc:
                raise ValueError(f'Invalid JSON in inventory for version {vdir}: {exc}')

        if not isinstance(inv, dict):
            raise ValueError(f'Inventory for version {vdir} must be a mapping of content to digest')

        # Each version inventory must contain all items present in the root inventory
        for name, root_digest in self.root_inventory.items():
            if name not in inv:
                raise ValueError(f'Item {name!r} missing in inventory for version {vdir}')
            ver_digest = inv[name]
            if ver_digest != root_digest:
                self.different_digests.setdefault(name, {})[vdir] = ver_digest

    return self

