def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    # Replace placeholders of the form {key} with corresponding values from url_args.
    def _repl(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))

    return re.sub(r'\{(\w+)\}', _repl, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        stripped = val.strip()
        if not stripped:
            return True
        if stripped.lower() in ('none', 'null', 'na', 'n/a'):
            return True
    return False

