def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])
    while queue:
        c = queue.pop()
        seen.add(c)
        for sub in c.__subclasses__():
            if sub not in seen:
                queue.add(sub)
    seen.remove(cls)
    return seen

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    return re.sub(r"^(['\"])(.*)\1$", r"\2", name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, shlex
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    if platform == 1:
        # POSIX: use shlex for correctness
        return shlex.split(s, posix=True)
    elif platform == 0:
        # Windows: split on whitespace unless inside quotes
        # Handles escaped quotes and backslashes
        pattern = r'''(?:"((?:[^"\\]|\\.)*)"|(\S+))'''
        parts = []
        for m in re.finditer(pattern, s):
            if m.group(1) is not None:
                part = m.group(1)
                # Unescape backslash-escaped characters
                part = re.sub(r'\\(.)', r'\1', part)
                parts.append(part)
            else:
                parts.append(m.group(2))
        return parts
    else:
        raise ValueError('Unsupported platform value: %r' % platform)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"git command failed: {result.stderr}")
    files = result.stdout.splitlines()
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    import re
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        return None
    if freq.lower() == "always":
        return None
    # Match a number followed by a unit (e.g., "3 weeks")
    m = re.match(r'^(\d+)\s*(\w+)$', freq, re.IGNORECASE)
    if not m:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")
    num = int(m.group(1))
    unit = m.group(2).lower()
    if unit in ('day', 'days'):
        return datetime.timedelta(days=num)
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=num)
    if unit in ('hour', 'hours'):
        return datetime.timedelta(hours=num)
    if unit in ('minute', 'minutes', 'min', 'mins'):
        return datetime.timedelta(minutes=num)
    if unit in ('second', 'seconds', 'sec', 'secs'):
        return datetime.timedelta(seconds=num)
    if unit in ('month', 'months'):
        return datetime.timedelta(days=30 * num)
    if unit in ('year', 'years'):
        return datetime.timedelta(days=365 * num)
    raise ValueError(f"Unknown time unit: {unit!r}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick string checks for common localhost names
    if host in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        # Resolve the host to all possible addresses
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be localhost
        return False

    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    return os.name == 'nt' and (
        'MSYSTEM' in os.environ or
        os.environ.get('OSTYPE', '').startswith('msys')
    )

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize inputs
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    # If args is a list of lists, use each for corresponding command
    if isinstance(args, list) and all(isinstance(a, list) for a in args):
        cmd_args_list = args
    else:
        # Use the same args for all commands
        cmd_args_list = [args] * len(commands)

    results = []
    for cmd, cmd_args in zip(commands, cmd_args_list):
        full_cmd = [cmd] + cmd_args
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")
        stderr = subprocess.DEVNULL if hide_stderr else None
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                capture_output=True,
                text=True,
                stderr=stderr
            )
            result.check_returncode()
        except subprocess.CalledProcessError as e:
            raise RuntimeError(
                f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}"
            ) from e
        results.append(result)
    return results

