def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type, return it unchanged
    if isinstance(seq, (list, tuple, str, bytes)):
        return (seq, type(seq))
    # Otherwise, derive a sequence from seq (e.g., from an iterator)
    if bufsize is None:
        seq_list = list(seq)
    else:
        seq_list = []
        for i, item in enumerate(seq):
            seq_list.append(item)
            if (i + 1) % bufsize == 0:
                # Buffer boundary reached; continue collecting
                pass
    return (seq_list, type(seq_list))

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dict is empty')
    # Determine where frequencies are stored
    if hasattr(self, '_freq') and hasattr(self, '_data'):
        freq_map = self._freq
        data_map = self._data
    else:
        # Assume each value is a tuple (value, freq)
        freq_map = {k: v[1] for k, v in self.items()}
        data_map = self
    min_key = min(freq_map, key=freq_map.get)
    if data_map is self:
        value = self.pop(min_key)
    else:
        value = data_map.pop(min_key)
    if hasattr(self, '_freq'):
        self._freq.pop(min_key)
    return (min_key, value)

