@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")
    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")
    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a YAML mapping")
    required_fields = ['name', 'type', 'schema']
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(name, seen):
        if name in seen:
            raise ValueError(f"Circular include detected for parser '{name}'")
        seen.add(name)
        parser = parser_dict.get(name, {})
        includes = parser.get('include', [])
        merged = {}
        for inc in includes:
            merged.update(_resolve(inc, seen))
        for key, val in parser.items():
            if key != 'include':
                merged[key] = val
        seen.remove(name)
        return merged

    resolved = {}
    for name in parser_dict:
        resolved[name] = _resolve(name, set())
    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Prefer value from spec if present
        if hasattr(self, 'spec') and arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]
        else:
            # Fallback to the option's own default
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

        # Handle nested dictionary options
        if isinstance(arg, DictOption) and arg.scheme:
            sub_defaults = arg.scheme.get_spec_defaults()
            if sub_defaults:
                defaults[arg.name] = sub_defaults

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {
        'old_arg': 'new_arg',
        'legacy_option': 'current_option',
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to their replacements.
    # This should be defined on the instance, e.g. self.deprecated_args = {'old_arg': 'new_arg'}
    deprecated_map = getattr(self, 'deprecated_args', {})
    if not deprecated_map:
        return

    for source_name, args in [('cli', cli_args), ('answer_file', answer_file_args)]:
        for key in list(args.keys()):
            if key in deprecated_map:
                new_key = deprecated_map[key]
                print(f"[{source_name}] Deprecated argument '{key}' detected. "
                      f"Use '{new_key}' instead.")
                # Optionally replace the deprecated key with the new one if the new key is not already set.
                if new_key not in args:
                    args[new_key] = args.pop(key)
                else:
                    # If both old and new are present, keep the new value and discard the old.
                    args.pop(key)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        return self._specs[command_name][argument_name]
    except KeyError:
        return None

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required_args', [])
    for key in required:
        if key not in args or args[key] is None:
            raise InvalidArgumentError(f"Missing required argument: {key}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        cond = opt.get('required_when')
        if cond is None:
            continue
        name = opt.get('name')
        if name is None:
            continue
        try:
            # If the condition is a callable, call it with command_name and args
            if callable(cond):
                if cond(command_name, args):
                    required.append(name)
                continue
            # If the condition is a string, evaluate it in a safe namespace
            if isinstance(cond, str):
                if eval(cond, {}, {'args': args, 'command_name': command_name}):
                    required.append(name)
                continue
            # If the condition is a tuple/list of (arg_name, expected_value)
            if isinstance(cond, (list, tuple)) and len(cond) == 2:
                arg_name, expected = cond
                if args.get(arg_name) == expected:
                    required.append(name)
                continue
        except Exception:
            # Ignore any errors in evaluating the condition
            pass
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    args_spec = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        spec = args_spec.get(arg_name, {})
        max_len = spec.get('length')
        if max_len is None:
            continue
        if not isinstance(max_len, int):
            raise TypeError(f"Length constraint for argument '{arg_name}' must be an integer")
        if max_len < 0:
            raise ValueError(f"Length constraint for argument '{arg_name}' must be non-negative")
        if value is None:
            continue
        try:
            val_len = len(value)
        except Exception:
            continue
        if val_len > max_len:
            raise ValueError(f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {max_len}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML.
    arg_defs = self.parsed_yaml.get('args', {})
    # Iterate over each provided argument.
    for name, value in args.items():
        # Locate the definition for this argument.
        if isinstance(arg_defs, dict):
            arg_def = arg_defs.get(name)
        else:  # list of single‑item dicts
            arg_def = None
            for item in arg_defs:
                if name in item:
                    arg_def = item[name]
                    break
        # If no definition is found, skip validation for this argument.
        if not arg_def:
            continue
        # If the definition specifies a list of allowed choices, validate it.
        choices = arg_def.get('choices')
        if choices is None:
            continue
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{name}': {value!r}. "
                f"Expected one of {choices!r}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self, 'min_', None)
    max_val = getattr(self, 'max_', None)
    for arg in args:
        if arg is None:
            continue
        if min_val is not None and arg < min_val:
            raise ValueError(f"Argument {arg} is less than minimum {min_val}")
        if max_val is not None and arg > max_val:
            raise ValueError(f"Argument {arg} is greater than maximum {max_val}")
    return args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        vars_dict = {}
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, list):
        extra_mapping = {}
        for d in extra_vars:
            if isinstance(d, dict):
                extra_mapping.update(d)
    elif isinstance(extra_vars, dict):
        extra_mapping = extra_vars
    else:
        raise ValueError("extra_vars must be a dict or list of dicts")
    vars_dict.update(extra_mapping)
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser's option definitions
    parser = self.parsers.get(parser_name)
    if not parser:
        return

    for opt in parser.options:
        if opt.name in values_dict:
            raw = values_dict[opt.name]
            # Prefer a custom convert method if available
            if hasattr(opt, "convert") and callable(opt.convert):
                try:
                    values_dict[opt.name] = opt.convert(raw)
                    continue
                except Exception:
                    pass
            # Fallback to the type attribute if present
            if hasattr(opt, "type") and opt.type:
                try:
                    values_dict[opt.name] = opt.type(raw)
                except Exception:
                    pass
    # values_dict is modified in place; no return value needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine the plugin spec file (default to plugin.json)
    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_file):
        # If the spec file does not exist, return an empty dict
        return {}

    # Load the spec JSON
    with open(spec_file, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

